def img(name,alt,cls='',eager=False):
 return f'<img src="{MEDIA+name}" alt="{alt}" width="1672" height="941" class="{cls}" '+('fetchpriority="high"' if eager else 'loading="lazy"')+'>'
def link(href,label,cls='text-link'):
 return f'<a class="{cls}" href="{href}">{label}<span aria-hidden="true">↗</span></a>'
def ul(items,cls='check-list'):
 return '<ul class="'+cls+'">'+''.join('<li>'+s+'</li>' for s in items)+'</ul>'
def header(active):
 items=[('services.html','Services'),('use-cases.html','Applications'),('deliverables.html','Deliverables'),('partners.html','Our approach')]
 nav=''.join(f'<a href="{f}" '+('class="active" aria-current="page"' if active==f else ('class="active"' if active in [s['file'] for s in services] and f=='services.html' else ''))+'>'+t+'</a>' for f,t in items)
 return f'''<a href="#main" class="skip-link">Skip to content</a><div class="topbar"><div class="container"><span>A KEELCORE initiative</span><span>Maritime expertise · Aerial perspective <b class="beta">BETA</b></span></div></div><header class="header"><div class="container nav-wrap"><a class="brand" href="index.html" aria-label="AIR MARINE home"><img src="assets/site/mark.svg" alt="" width="42" height="42"><span><strong>AIR MARINE</strong><small>DRONE SERVICES</small></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation" type="button">Menu <span aria-hidden="true">+</span></button><nav id="navigation" aria-label="Main navigation">{nav}<a class="button small" href="contact.html" {'aria-current="page"' if active=='contact.html' else ''}>Discuss a project <span aria-hidden="true">↗</span></a></nav></div></header>'''
