def page(file,title,desc,content):
 html=f'''<!doctype html><html lang="en" id="top"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | AIR MARINE</title><meta name="description" content="{desc}"><meta name="theme-color" content="#103e46"><link rel="canonical" href="{BASE+file}"><meta property="og:title" content="{title} | AIR MARINE"><meta property="og:description" content="{desc}"><meta property="og:type" content="website"><meta property="og:image" content="{BASE}assets/site/harbour.webp"><link rel="icon" type="image/svg+xml" href="assets/site/mark.svg"><link rel="stylesheet" href="assets/site/site.css"><script src="assets/site/site.js" defer></script><noscript><style>.menu-toggle{{display:none}}#navigation{{display:flex;position:static;flex-wrap:wrap}}.nav-wrap{{height:auto;flex-wrap:wrap;padding:18px 0}}[role=tablist]{{display:none}}.sample-panel[hidden]{{display:block!important}}</style></noscript></head><body>{header(file)}<main id="main">{content}</main>{footer()}</body></html>'''
 (ROOT/file).write_text(html)
def crumb(current,parent=None):
 return '<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="index.html">Home</a><span aria-hidden="true">/</span>'+ ('<a href="services.html">Services</a><span aria-hidden="true">/</span>' if parent else '')+'<span aria-current="page">'+current+'</span></nav>'
def intro(kicker,title,desc,current):
 return f'<section class="page-intro"><div class="container">{crumb(current)}<p class="eyebrow">{kicker}</p><div class="intro-row"><h1>{title}</h1><p>{desc}</p></div></div></section>'
